//! @generated by xtask split-relics.
use super::prelude::*;

pub(crate) fn on_before_side_turn_start_rainbow_ring(
    state: &mut CombatState,
    side: Side,
) -> EffectResult {
    if side != Side::Player {
        return EffectResult::NotImplemented;
    }
    if let Some(r) = rainbow_ring_relic_mut(state) {
        r.counter = 0;
    }
    EffectResult::Resolved
}

pub(crate) fn on_after_card_played_rainbow_ring(
    state: &mut CombatState,
    ctx: &CardEventCtx,
) -> EffectResult {
    if !player_owns_relic(state, crate::RelicKind::RainbowRing) {
        return EffectResult::NotImplemented;
    }
    let Some(uid) = ctx.card_uid else {
        return EffectResult::NotImplemented;
    };
    // C# `RainbowRing.AfterCardPlayed` gates the WHOLE body (including the
    // per-type counting) on `ActivationCountThisTurn < 1` — once it has fired
    // this turn it stops counting entirely and cannot re-grant. Honor that cap
    // before touching the per-type mask.
    if rainbow_ring_relic_mut(state).is_some_and(|r| r.counter & RAINBOW_RING_MASK_ACTIVATED != 0) {
        return EffectResult::Resolved;
    }
    let bit = match crate::card_by_uid(&state.cards, uid).map(|c| c.card_type) {
        Some(crate::cards::CardType::Attack) => RAINBOW_RING_MASK_ATTACK,
        Some(crate::cards::CardType::Skill) => RAINBOW_RING_MASK_SKILL,
        Some(crate::cards::CardType::Power) => RAINBOW_RING_MASK_POWER,
        _ => return EffectResult::NotImplemented,
    };
    let new_mask = if let Some(r) = rainbow_ring_relic_mut(state) {
        r.counter |= bit;
        r.counter
    } else {
        return EffectResult::NotImplemented;
    };
    if new_mask & RAINBOW_RING_MASK_ALL == RAINBOW_RING_MASK_ALL {
        // C# increments `ActivationCountThisTurn` (does NOT clear the per-type
        // counters) — set the sticky activated bit so further cards this turn
        // are capped out by the guard above. The whole mask is cleared at
        // turn start / combat end.
        if let Some(r) = rainbow_ring_relic_mut(state) {
            r.counter |= RAINBOW_RING_MASK_ACTIVATED;
        }
        if let Some(player_uid) = state.player.creature_uid {
            apply_power_to_creature(
                state,
                player_uid,
                PowerKind::Strength,
                RAINBOW_RING_STRENGTH,
            );
            apply_power_to_creature(
                state,
                player_uid,
                PowerKind::Dexterity,
                RAINBOW_RING_DEXTERITY,
            );
        }
    }
    EffectResult::Resolved
}

pub(crate) fn on_after_combat_end_rainbow_ring(state: &mut CombatState) -> EffectResult {
    let Some(r) = rainbow_ring_relic_mut(state) else {
        return EffectResult::NotImplemented;
    };
    r.counter = 0;
    EffectResult::Resolved
}

pub(crate) fn install() {
    register_before_side_turn_start(
        RelicId::RainbowRing,
        on_before_side_turn_start_rainbow_ring as BeforeSideTurnStartFn,
    );
    register_after_card_played(
        RelicId::RainbowRing,
        on_after_card_played_rainbow_ring as AfterCardPlayedFn,
    );
    register_owned_after_combat_end(
        RelicId::RainbowRing,
        crate::RelicKind::RainbowRing,
        on_after_combat_end_rainbow_ring as AfterCombatEndFn,
    );
}
